import{_ as l,o as a,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"CDS Infernalis (Day 2.2) -- OSD: Transactions","description":"","frontmatter":{"title":"CDS Infernalis (Day 2.2) -- OSD: Transactions","date":"2015-03-07T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Ceph","Distributed Storage","Hadoop Integration","Rados Gateway","SEFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Transactions.md","filePath":"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Transactions.md","lastUpdated":1780459816000}'),r={name:"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Transactions.md"};function s(n,i,e,p,_,g){return a(),o("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph Rados Gateway的Hadoop文件接口设计与讨论</p><p><strong>参会人员</strong>： SE Patrick，其他相关研发人员</p><p><strong>会议内容</strong>：</p><p><strong>1. 背景介绍</strong></p><ul><li>项目旨在为Hadoop提供基于SEFS的参考解决方案，基于Stack Sahara项目，该项目基于Swift和UFS。</li><li>由于存储服务器与Hadoop集群位于隔离网络，无法使用Hadoop与FFS插件，因此采用SEF Ros Gateway作为连接器。</li><li>利用Caching Tier技术，在Rados Skateway服务器中使用SSD缓存数据。</li></ul><p><strong>2. 解决方案概述</strong></p><ul><li>方案包含四个组件：Rgw FS、RW Proxy、RW Cluster和Caching Tier。</li><li>Rgw FS作为Hadoop插件，使Hadoop可以与Rados Skateway目录通信。</li><li>RW Proxy负责获取数据块位置，类似于HDFS的NameNode。</li><li>RW Cluster使用Caching Tier技术，将数据缓存到SSD中。</li></ul><p><strong>3. 关键技术讨论</strong></p><ul><li><strong>RW Proxy</strong>： <ul><li>负责获取数据块位置，需要理解Ceph对象到Ceph对象的映射关系。</li><li>需要监控RW实例，以便进行故障转移。</li><li>可以通过增加Gateway管理RESTful命令来实现。</li></ul></li><li><strong>Caching Tier</strong>： <ul><li>使用SSD缓存数据，提高读取性能。</li><li>需要配置专门的chunk size和RW Max chunk size。</li></ul></li><li><strong>数据读取流程</strong>： <ul><li>Hadoop作业通过RW FS读取数据。</li><li>RW Proxy根据数据位置选择最接近的RW实例。</li><li>RW实例从Caching Tier读取数据。</li></ul></li><li><strong>数据写入流程</strong>： <ul><li>Hadoop作业通过RW Proxy写入数据。</li><li>RW Proxy将数据写入Caching Tier。</li><li>RW实例将数据写入Ceph集群。</li></ul></li></ul><p><strong>4. 讨论与决定</strong></p><ul><li><strong>RW Proxy</strong>： <ul><li>可以通过增加Gateway管理RESTful命令来实现故障转移。</li><li>可以使用多个副本来提高读取性能。</li></ul></li><li><strong>Caching Tier</strong>： <ul><li>需要配置专门的chunk size和RW Max chunk size。</li></ul></li><li><strong>数据写入</strong>： <ul><li>Hadoop作业写入数据时，不会覆盖现有对象，需要配置新的对象名称。</li></ul></li></ul><p><strong>5. 后续行动计划</strong></p><ul><li>完成RW Proxy和Caching Tier的实现。</li><li>对RW FS进行优化，减少对头对象的读取。</li><li>将解决方案集成到Stack Sahara项目中。</li></ul><p><strong>6. 其他讨论</strong></p><ul><li>讨论了使用Hadoop直接访问CFS的性能问题。</li><li>认为在RW和Swift之间引入中间件可以提高性能。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了Ceph Rados Gateway的Hadoop文件接口设计方案，并确定了后续的行动计划。该方案旨在提高Hadoop在Ceph存储系统上的性能和可靠性。</p>',18)])])}const d=l(r,[["render",s]]);export{u as __pageData,d as default};
